// Unit tests for src/crypto/p256_ecdsa.S (PLAN.MD Phase 16.5/16.6)
//
// Sign vectors: (hash, d, k) triples with their expected (r,s), computed
// by a plain Python transliteration of the ECDSA signing equations
// using this repo's own validated field/scalar/point arithmetic, then
// independently cross-checked against `cryptography` (OpenSSL)'s own
// verify() before being embedded here -- so both r/s correctness AND
// real-world interoperability are covered. Each vector also carries the
// signer's public key, so the same signature is fed straight into
// p256_ecdsa_verify for a full sign -> verify roundtrip.
//
// Verify vectors: real signatures produced by `cryptography` (OpenSSL)
// itself, fed into p256_ecdsa_verify -- genuine interop in the other
// direction, plus tamper tests that must be rejected.

#include "test_harness.h"

