    __asm__("p256_ecdsa_sign_with_k");
extern int64_t p256_ecdsa_verify(const uint8_t hash[32], const uint8_t sig_r[32],
                                  const uint8_t sig_s[32], const uint8_t qx[32],
                                  const uint8_t qy[32])
    __asm__("p256_ecdsa_verify");

